export interface HostileMilitaryPowerArgs {
  who: string;
  safetyBuffer?: boolean;
  value: number | readonly [PdxOp, number];
}

/**
 * Returns the hostile military power in the system (galactic_object scope) as perceived by the given country,optionally multiplied by ENEMY_FLEET_POWER_MULT as a safety buffer.
 * ```
 * optionally multiplied by ENEMY_FLEET_POWER_MULT as a safety buffer.
 * hostile_military_power = { who = root safety_buffer = yes value > 5000 }
 * ```
 */
export function hostileMilitaryPower(args: HostileMilitaryPowerArgs): Trigger<"system"> {
  const entries: PdxEntry[] = [];
  entries.push(kv("who", args.who));
  if (args.safetyBuffer !== undefined) {
    entries.push(kv("safety_buffer", args.safetyBuffer));
  }
  entries.push(
    typeof args.value === "object"
      ? cmp("value", args.value[0], args.value[1])
      : kv("value", args.value)
  );
  return trigger([block("hostile_military_power", entries)]);
}

